import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadPalaData(){const e=readFileSync(resolve(__dirname,"../../frontend/pala-wetland-explorer/pala-data.js"),"utf-8");return new Function(e+"\nreturn { PALA_INFO, ECOLOGY_HYDROLOGY, BIRD_FISH_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Pala Wetland Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadPalaData()}),describe("PALA_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.PALA_INFO.id).toBe("pala-wetland"),expect(e.PALA_INFO.name).toBe("Pala Wetland"),expect(e.PALA_INFO.ramsarYear).toBe(2021),expect(e.PALA_INFO.ramsarSiteNo).toBe(2460),expect(e.PALA_INFO.state).toBe("Mizoram")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.PALA_INFO.quickStats)).toBe(!0),expect(e.PALA_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains overview, freshwater ecology, legend, and conservation status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.freshwaterEcology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.legend).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()})}),describe("BIRD_FISH_SPECIES catalog",()=>{it("is a non-empty array of species",()=>{expect(Array.isArray(e.BIRD_FISH_SPECIES)).toBe(!0),expect(e.BIRD_FISH_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes White-winged Wood Duck and Great Hornbill",()=>{const t=e.BIRD_FISH_SPECIES.find(e=>"white-winged-wood-duck"===e.id),a=e.BIRD_FISH_SPECIES.find(e=>"great-hornbill"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"pala-wetland"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../pala-wetland-explorer/index.html")})})});